/// Returns true iff the given data type belongs to the given kind according to:
/// - Bool kind: only Bool data type.
/// - SignedInteger kind: Int8, Int16, Int32, Int64.
/// - UnsignedInteger kind: UInt8, UInt16, UInt32, UInt64.
/// - Integral kind: any signed OR unsigned integer.
/// - RealFloating kind: Float16, Float32, Float64.
/// - ComplexFloating kind: Complex64, Complex128.
/// - Numeric kind: Bool, signed integer, unsigned integer, real floating, or complex floating.
fn numpy_isdtype(dtype: NumpyDType, kind: DTypeKind) -> bool {
    match kind {
        DTypeKind::Bool => {
            dtype == NumpyDType::Bool
        }
        DTypeKind::SignedInteger => {
            matches!(dtype,
                NumpyDType::Int8 |
                NumpyDType::Int16 |
                NumpyDType::Int32 |
                NumpyDType::Int64)
        }
        DTypeKind::UnsignedInteger => {
            matches!(dtype,
                NumpyDType::UInt8 |
                NumpyDType::UInt16 |
                NumpyDType::UInt32 |
                NumpyDType::UInt64)
        }
        DTypeKind::Integral => {
            // Integral = SignedInteger OR UnsignedInteger
            numpy_isdtype(dtype, DTypeKind::SignedInteger) ||
            numpy_isdtype(dtype, DTypeKind::UnsignedInteger)
        }
        DTypeKind::RealFloating => {
            matches!(dtype,
                NumpyDType::Float16 |
                NumpyDType::Float32 |
                NumpyDType::Float64)
        }
        DTypeKind::ComplexFloating => {
            matches!(dtype,
                NumpyDType::Complex64 |
                NumpyDType::Complex128)
        }
        DTypeKind::Numeric => {
            // Numeric = Bool OR SignedInteger OR UnsignedInteger OR RealFloating OR ComplexFloating
            dtype == NumpyDType::Bool ||
            numpy_isdtype(dtype, DTypeKind::SignedInteger) ||
            numpy_isdtype(dtype, DTypeKind::UnsignedInteger) ||
            numpy_isdtype(dtype, DTypeKind::RealFloating) ||
            numpy_isdtype(dtype, DTypeKind::ComplexFloating)
        }
    }
}

